<?php $super = app(\App\Services\AuthService::class)->isSuperAdmin(); $locked = !$super || ($role && $role['name']==='super_admin'); ?>
<div class="dash-head"><div><h1><?= $role ? 'Role: '.e($role['label']) : 'Create role' ?></h1><p class="sub">Only Super Admin can change grants. Grant and assignment permissions are reserved; no grant workflow is available.</p></div><a class="btn btn-light" href="<?= e(base_url('admin/roles')) ?>">Back to roles</a></div>
<section class="panel"><form method="post" action="<?= e(base_url($role ? 'admin/roles/'.(int)$role['id'] : 'admin/roles')) ?>">
<?= csrf_field() ?>
<div class="grid-2"><div class="field"><label for="name">Role key</label><input class="input" id="name" name="name" pattern="[a-z][a-z0-9_]{2,49}" maxlength="50" required value="<?= e((string)($role['name'] ?? '')) ?>" <?= $locked?'disabled':($role && in_array($role['name'],\App\Services\RbacService::SYSTEM_ROLES,true) ? 'readonly' : '') ?>></div><div class="field"><label for="label">Display name</label><input class="input" id="label" name="label" maxlength="100" required value="<?= e((string)($role['label'] ?? '')) ?>" <?= $locked?'disabled':'' ?>></div></div>
<div class="field"><label for="description">Description</label><input class="input" id="description" name="description" maxlength="255" value="<?= e((string)($role['description'] ?? '')) ?>" <?= $locked?'disabled':'' ?>></div>
<h2>Permissions</h2><?php $group=''; foreach ($permissions as $p): if ($group !== $p['group_name']): if ($group!==''): ?></div><?php endif; $group=$p['group_name']; ?><h3><?= e(ucwords(str_replace('_',' ',$group))) ?></h3><div class="choice-grid"><?php endif; ?><label class="choice"><input type="checkbox" name="permissions[]" value="<?= (int)$p['id'] ?>" <?= in_array((int)$p['id'],$grants,true)?'checked':'' ?> <?= $locked?'disabled':'' ?>><span><b><?= e($p['name']) ?></b><em><?= e($p['label']) ?></em></span></label><?php endforeach; if ($group!==''): ?></div><?php endif; ?>
<?php if (!$locked): ?><div class="form-actions"><button class="btn btn-brand" type="submit">Save role</button></div><?php endif; ?></form>
<?php if ($role && !$locked && !in_array($role['name'],\App\Services\RbacService::SYSTEM_ROLES,true)): ?><form method="post" action="<?= e(base_url('admin/roles/'.(int)$role['id'].'/delete')) ?>" data-confirm="Delete this role? Only unused roles can be deleted."><?= csrf_field() ?><button class="btn btn-outline-brand" type="submit">Delete unused role</button></form><?php endif; ?></section>
